//! Time and drying. The painting has a clock (`c.wait(minutes)`), and what a
//! brush does depends on how far the paint under it has dried.
//!
//! Top row: the same wet-into-wet blend (a dark blue brought up into a warm
//! light field, then worked across the join with a clean brush), started
//! at 0 min, 30 min, 3 h and 24 h after the light field was laid.
//! Open paint blends; at 3 h the lead-white field is tacky, so the blue
//! catches and drags in broken patches; at 24 h it is touch-dry and the
//! blue sits on top with a crisp join.
//!
//! Bottom row: a light scumble dragged over an umber underlayer that is
//! tacky (3 h) and touch-dry (24 h); a pale glaze with a Gaussian falloff
//! (1/e radius 55 units) over a dark bone-black field.

use paint::drying::drier;
use paint::{Canvas, Gesture, Held, Mask, Orient, Paint, Pigment, Stage, Style, Tool, hex};

const TOP: (f32, f32) = (30.0, 330.0);
const BOT: (f32, f32) = (370.0, 640.0);

/// Panel `k` of `n` across the canvas: (x0, x1) in units.
fn panel(k: usize, n: usize) -> (f32, f32) {
    let w = 1000.0 / n as f32;
    (k as f32 * w + 20.0, (k + 1) as f32 * w - 20.0)
}

/// Lay a field, about one lean coat, with a hog flat in level, overlapping
/// strokes.
fn field(c: &mut Canvas, p: Paint, x: (f32, f32), y: (f32, f32), seed: u64) {
    let mut h = Held::new(Tool::hog_flat(14.0), seed);
    let mut yy = y.0 + 5.0;
    let mut k = 0;
    while yy < y.1 - 4.0 {
        if k % 2 == 0 {
            h.reload(p, 0.45);
        }
        c.drag(&mut h, &Gesture::new(vec![(x.0 + 2.0, yy), (x.1 - 2.0, yy + 1.5)]).pressure(0.85, 0.8).orient(Orient::Across), None);
        yy += 6.0;
        k += 1;
    }
}

/// The blend: dark blue brought up to the join, then a clean flat worked
/// up and down across it, then a light pass along it.
fn blend(c: &mut Canvas, x: (f32, f32), join: f32, seed: u64) {
    let blue = Paint::body(hex("#2c3a58")).with_drying(drier::SMALT);
    field(c, blue, x, (join, TOP.1), seed);
    let mut h = Held::new(Tool::hog_flat(10.0), seed + 1);
    let mut xx = x.0 + 6.0;
    let mut up = true;
    while xx < x.1 - 5.0 {
        let (a, b) = if up { (join + 28.0, join - 28.0) } else { (join - 28.0, join + 28.0) };
        c.drag(&mut h, &Gesture::new(vec![(xx, a), (xx + 2.0, b)]).pressure(0.6, 0.5).orient(Orient::Across), None);
        h.wipe(0.3);
        xx += 6.0;
        up = !up;
    }
    let mut soft = Held::new(Tool::badger(22.0), seed + 2);
    for dy in [-8.0, 0.0, 8.0] {
        c.drag(&mut soft, &Gesture::new(vec![(x.0 + 4.0, join + dy), (x.1 - 4.0, join + dy)]).pressure(0.35, 0.3), None);
    }
}

/// A scumble: a hog flat with a little stiff light paint, dragged lightly.
fn scumble(c: &mut Canvas, x: (f32, f32), y: (f32, f32), seed: u64) {
    let light = Paint::scumble(hex("#e4dcc4")).with_stiff(0.9).with_drying(drier::LEAD_WHITE);
    let mut h = Held::new(Tool::hog_flat(18.0), seed);
    let mut yy = y.0 + 25.0;
    while yy < y.1 - 20.0 {
        h.reload(light, 0.35);
        c.drag(&mut h, &Gesture::new(vec![(x.0 + 10.0, yy), (x.1 - 10.0, yy - 6.0)]).pressure(0.45, 0.35).orient(Orient::Across), None);
        yy += 30.0;
    }
}

fn say(c: &Canvas, t0: f64, what: &str, at: &[(&str, (f32, f32))]) {
    let s: Vec<String> = at.iter().map(|(n, p)| format!("{n} {:?}", c.drying_at(p.0, p.1))).collect();
    println!("{:>7.0} min  {what}: {}", c.clock() - t0, s.join(", "));
}

fn main() {
    let o = paintings::run::Run::new("study_time");
    let st = Style::friedrich();
    let mut c = st.prepare(o.width, 1000.0 / 670.0, o.seed);
    // (the ground was dried: the clock starts weeks in)
    let t0 = c.clock();
    let join = 0.5 * (TOP.0 + TOP.1);
    let warm = Paint::body(hex("#e2cfa6")).with_drying(drier::LEAD_WHITE);
    let umber = Paint::body(hex("#4a3a2a")).with_drying(drier::UMBER);
    let slate = Paint::body(hex("#343a44")).with_drying(drier::BONE_BLACK);
    // t = 0: the light fields of the blends, the scumbles' underlayer, the
    // glaze's dark field
    for k in 0..4 {
        field(&mut c, warm, panel(k, 4), (TOP.0, join + 6.0), 10 + k as u64);
    }
    for k in 0..2 {
        field(&mut c, umber, panel(k, 3), BOT, 20 + k as u64);
    }
    field(&mut c, slate, panel(2, 3), BOT, 30);
    let top = |k: usize| (0.5 * (panel(k, 4).0 + panel(k, 4).1), join - 40.0);
    let bot = |k: usize| (0.5 * (panel(k, 3).0 + panel(k, 3).1), 0.5 * (BOT.0 + BOT.1));
    say(&c, t0, "laid", &[("light", top(0)), ("umber", bot(0)), ("slate", bot(2))]);
    blend(&mut c, panel(0, 4), join, 100);
    c.wait(30.0);
    say(&c, t0, "30 min", &[("light", top(1))]);
    assert_eq!(c.drying_at(top(1).0, top(1).1), Stage::Open, "the light field is open at 30 min");
    blend(&mut c, panel(1, 4), join, 200);
    c.wait(150.0);
    say(&c, t0, "3 h", &[("light", top(2)), ("umber", bot(0)), ("slate", bot(2))]);
    // (the same at any width: a film dries by its thickness over a few
    // millimeters, `drying::FILM_MM`, not per pixel)
    assert_eq!(c.drying_at(top(2).0, top(2).1), Stage::Tacky, "the light field is tacky at 3 h");
    assert_eq!(c.drying_at(bot(0).0, bot(0).1), Stage::Tacky, "the umber is tacky at 3 h");
    assert_eq!(c.drying_at(bot(2).0, bot(2).1), Stage::Open, "the slate (bone black) is still open at 3 h");
    blend(&mut c, panel(2, 4), join, 300);
    scumble(&mut c, panel(0, 3), BOT, 400);
    c.wait(21.0 * 60.0);
    say(&c, t0, "next day", &[("light", top(3)), ("umber", bot(1)), ("slate", bot(2))]);
    assert_eq!([top(3), bot(1), bot(2)].map(|p| c.drying_at(p.0, p.1)), [Stage::Dry, Stage::Dry, Stage::Tacky], "next day: light and umber dry, slate tacky");
    blend(&mut c, panel(3, 4), join, 500);
    scumble(&mut c, panel(1, 3), BOT, 600);
    // the glaze: a pale veil over the slate with a long Gaussian falloff,
    // through a blurred panel mask (float residue out to the edges)
    let p = panel(2, 3);
    let m = Mask::from_fn(c.frame(), move |x, y| if x > p.0 && x < p.1 && y > BOT.0 && y < BOT.1 { 1.0 } else { 0.0 }).blur(2.0);
    let (gx, gy) = bot(2);
    c.glaze(&Pigment::semi(hex("#e8dcc0")), Some(&m), move |x, y| {
        let d = ((x - gx).powi(2) + (y - gy).powi(2)).sqrt();
        1.2 * (-(d / 55.0).powi(2)).exp()
    });
    say(&c, t0, "glazed (dry)", &[("slate", bot(2))]);
    c.relief(0.3, 0.02);
    o.save(&mut c);
}

//! Brush physics study sheet: each row tests one behavior.

use paint::{Gesture, Held, Orient, Paint, Tool, hex};

fn main() {
    let o = paintings::run::Run::new("study_brushes");
    // lead-white priming on linen
    let mut c = paint::Canvas::new(o.width, 1.5, hex("#ece6d8")).with_linen(paint::Linen::fine(3));

    let ultramarine = hex("#1f2a78");
    let sienna = hex("#8a3b12");
    let sap = hex("#4f6b1c");
    let ivory_black = hex("#1a1816");
    let cad_yellow = hex("#f2c200");
    let cobalt = hex("#1c4fa0");
    let crimson = hex("#9a1030");
    let white = hex("#f4f1e8");
    let ochre = hex("#c08a2a");

    let wave = |x0: f32, y: f32, len: f32, amp: f32| -> Vec<(f32, f32)> {
        (0..6).map(|i| {
            let t = i as f32 / 5.0;
            (x0 + t * len, y + (t * std::f32::consts::TAU).sin() * amp)
        }).collect()
    };

    // ---- row 1: each tool, fully loaded, one S-stroke
    let tools = [
        (Tool::round_sable(8.0), ultramarine),
        (Tool::hog_flat(20.0), sienna),
        (Tool::filbert(16.0), sap),
        (Tool::fan(26.0), ivory_black),
        (Tool::rigger(1.6), ivory_black),
    ];
    for (i, (t, col)) in tools.iter().enumerate() {
        let mut b = Held::new(t.clone(), 10 + i as u64);
        b.load(Paint::body(*col), 1.0);
        let x = 30.0 + i as f32 * 190.0;
        c.drag(&mut b, &Gesture::new(wave(x, 60.0, 160.0, 14.0)), None);
    }

    // ---- row 2: pressure falls off → dry brush over the weave
    let mut b = Held::new(Tool::hog_flat(22.0), 20);
    b.load(Paint::body(sienna), 0.8);
    c.drag(&mut b, &Gesture::line((30.0, 150.0), (470.0, 150.0)).pressure(1.0, 0.12).ramps(0.03, 0.02), None);
    let mut b = Held::new(Tool::round_sable(10.0), 21);
    b.load(Paint::body(ultramarine), 0.5);
    c.drag(&mut b, &Gesture::new(wave(520.0, 150.0, 450.0, 8.0)).pressure(0.9, 0.3), None);

    // ---- row 3: wet into wet — yellow dragged through wet blue picks it up
    let mut b = Held::new(Tool::hog_flat(24.0), 30);
    for k in 0..4 {
        b.reload(Paint::body(cobalt), 1.0);
        let y = 215.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((30.0, y), (330.0, y)).pressure(0.9, 0.8), None);
    }
    let mut b = Held::new(Tool::filbert(14.0), 31);
    for k in 0..5 {
        b.reload(Paint::body(cad_yellow), 1.0);
        let x = 60.0 + k as f32 * 55.0;
        c.drag(&mut b, &Gesture::line((x, 200.0), (x + 20.0, 290.0)).pressure(0.95, 0.9), None);
    }
    // white into wet dark
    let mut b = Held::new(Tool::hog_flat(24.0), 32);
    for k in 0..4 {
        b.reload(Paint::body(ivory_black), 1.0);
        let y = 215.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((370.0, y), (620.0, y)), None);
    }
    let mut b = Held::new(Tool::round_sable(9.0), 33);
    b.load(Paint::body(white), 1.0);
    c.drag(&mut b, &Gesture::new(vec![(390.0, 280.0), (450.0, 215.0), (520.0, 280.0), (600.0, 210.0)]).pressure(0.9, 0.7), None);

    // blender: two wet colors side by side, badger zigzag across the join
    let mut b = Held::new(Tool::hog_flat(24.0), 34);
    for k in 0..5 {
        b.reload(Paint::body(ochre), 1.0);
        let y = 205.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((660.0, y), (810.0, y)), None);
        b.reload(Paint::body(crimson), 1.0);
        c.drag(&mut b, &Gesture::line((810.0, y), (970.0, y)), None);
    }
    let mut bl = Held::new(Tool::badger(34.0), 35);
    let zig: Vec<(f32, f32)> = (0..10).map(|i| (790.0 + if i % 2 == 0 { -18.0 } else { 18.0 }, 200.0 + i as f32 * 10.0)).collect();
    c.drag(&mut bl, &Gesture::new(zig).pressure(0.5, 0.5), None);
    let zig2: Vec<(f32, f32)> = (0..10).map(|i| (840.0 + if i % 2 == 0 { -14.0 } else { 14.0 }, 200.0 + i as f32 * 10.0)).collect();
    c.drag(&mut bl, &Gesture::new(zig2).pressure(0.35, 0.35), None);

    // ---- row 4: let it dry, then glaze crimson over part of rows 3
    c.dry();
    let mut g = Held::new(Tool::filbert(30.0), 40);
    for k in 0..3 {
        g.reload(Paint::glaze(crimson), 1.0 * 0.3);
        let y = 215.0 + k as f32 * 22.0;
        c.drag(&mut g, &Gesture::line((180.0, y), (520.0, y)).pressure(0.6, 0.6), None);
    }

    // ---- row 5: 60 short hog-flat strokes at a fixed angle (-0.9 rad) in
    // five greens, and 14 fan scumble dabs
    let mut b = Held::new(Tool::hog_flat(12.0), 50);
    let greens = [hex("#5a7a3a"), hex("#7d9a4a"), hex("#3f5f3a"), hex("#9aa860"), hex("#6f8fa0")];
    let mut r = paint::Rng::new(5);
    for k in 0..60 {
        b.reload(Paint::body(greens[k % greens.len()]), 0.7);
        let x = 40.0 + r.range(0.0, 380.0);
        let y = 340.0 + r.range(0.0, 90.0);
        let a = -0.9f32;
        c.drag(&mut b, &Gesture::line((x, y), (x + a.cos() * 18.0, y + a.sin() * 18.0)).orient(Orient::Fixed(a + std::f32::consts::FRAC_PI_2)).pressure(0.85, 0.7), None);
    }
    let mut fan = Held::new(Tool::fan(30.0), 51);
    for k in 0..14 {
        fan.reload(Paint::scumble(if k % 2 == 0 { hex("#3d5a2a") } else { hex("#8aa050") }), 0.5 * 0.6);
        let x = 480.0 + k as f32 * 34.0;
        let y = 400.0 + r.range(-20.0, 20.0);
        c.drag(&mut fan, &Gesture::line((x, y + 10.0), (x + 6.0, y - 30.0)).orient(Orient::Across).pressure(0.6, 0.3), None);
    }

    // ---- row 6: one dirty brush dragged across wet colors without cleaning
    let bands = [cobalt, cad_yellow, crimson, white, sap];
    let mut b = Held::new(Tool::hog_flat(26.0), 60);
    for (k, col) in bands.iter().enumerate() {
        b.reload(Paint::body(*col), 1.0);
        let x = 40.0 + k as f32 * 70.0;
        c.drag(&mut b, &Gesture::line((x, 480.0), (x, 610.0)).orient(Orient::Across), None);
    }
    let mut b = Held::new(Tool::filbert(18.0), 61);
    b.load(Paint::body(white), 0.6);
    for k in 0..3 {
        let y = 505.0 + k as f32 * 40.0;
        c.drag(&mut b, &Gesture::line((25.0, y), (400.0, y + 8.0)).pressure(0.9, 0.9), None);
    }
    // rigger: eight wavy upward strokes, pressure falling from 0.9 to 0.2
    let mut rg = Held::new(Tool::rigger(1.4), 62);
    for k in 0..8 {
        rg.reload(Paint::body(ivory_black), 1.0);
        let x = 500.0 + k as f32 * 55.0;
        let pts: Vec<(f32, f32)> = (0..6).map(|i| (x + (i as f32 * 1.7).sin() * 8.0 + i as f32 * 6.0, 620.0 - i as f32 * 22.0)).collect();
        c.drag(&mut rg, &Gesture::new(pts).pressure(0.9, 0.2).ramps(0.02, 0.6), None);
    }

    c.relief(0.7, 0.04);
    o.save(&mut c);
}
//! Style profiles: a support and ground, a tool kit, a palette and
//! handling presets.
//!
//! A `Style` is data: linen, ground layers, five tools (`broad`, `body`,
//! `detail`, `line`, `blender`), a palette, medium fractions and blending
//! settings. Paintings ask the style for a `Handling` and supply geometry
//! and color.
//!
//! The handling presets (`broad`, `body`, `detail`, `hatch`, `glaze`,
//! `blend`) choose stroke lengths, paths, pressure variation, placement and
//! order. Their fields are public and are listed in each preset below;
//! every one can be changed with the `Handling` builder methods, for
//! example stroke direction (`angle`), crossing (`cross`), bow (`curve`),
//! wander (`drift`) and the order an area is worked in (`order`, `sweep`).

use crate::bristle::{Orient, Tool};
use crate::canvas::Canvas;
use crate::color::{Rgb, hex};
use crate::handling::Handling;
use crate::mask::Mask;
use crate::palette::Palette;
use crate::surface::Linen;

/// Mean thickness (µm) a brushed ground (`brush_ground`) lays for a load of
/// the priming brush: about `BRUSHED_UM_AT_FULL * load^BRUSHED_EXP`
/// (measured: load 0.160 lays 37.8 µm, 0.279 lays 73.7, 0.386 lays 111.3;
/// a fuller brush leaves fewer gaps for the filling dabs to close, and
/// laying off takes a thin film along with it, so the thickness grows a
/// little faster than the load).
const BRUSHED_UM_AT_FULL: f32 = 364.0;
const BRUSHED_EXP: f32 = 1.24;

/// How a ground layer is put on.
#[derive(Clone, Copy, Debug)]
pub enum Apply {
    /// Spread with a priming knife: levels the weave; `texture` 0..1 is the
    /// waviness of the knife.
    Knife { texture: f32 },
    /// Rolled on: a fine, even orange-peel texture.
    Roller,
    /// Brushed with a broad hog brush: spread in crossing strokes whose
    /// direction drifts over the canvas, then laid off with light passes of
    /// the clean brush; fine, broken bristle striations stay (see
    /// `brush_ground`).
    Brush,
}

/// One preparation layer.
#[derive(Clone, Copy, Debug)]
pub struct Ground {
    pub color: Rgb,
    pub hiding: f32,
    /// Thickness, µm.
    pub um: f32,
    /// Stiffness of the priming paste (0 fluid .. 1 stiff).
    pub stiff: f32,
    pub apply: Apply,
}

#[derive(Clone, Debug)]
pub struct Style {
    pub name: &'static str,
    /// Physical width of a typical canvas, mm.
    pub width_mm: f32,
    pub linen: Linen,
    /// Color of the raw linen.
    pub raw: Rgb,
    /// Preparation layers, bottom first.
    pub ground: Vec<Ground>,
    /// Tool for large areas of thin paint (`broad`).
    pub broad: Tool,
    /// Tool for body color (`body`).
    pub body: Tool,
    /// Tool for small marks and edges (`detail`, `hatch`).
    pub detail: Tool,
    /// Tool for lines (`line_tool`).
    pub line: Tool,
    /// Tool for softening wet passages (`blend`; None: no blender).
    pub blender: Option<Tool>,
    /// Blending passes over broad areas.
    pub blend_passes: usize,
    /// Pressure used when blending (light = gentle fusing).
    pub blend_pressure: f32,
    /// The tube paints every preset mixes from.
    pub palette: Palette,
    /// Fraction of oil medium in the paint for body color (`body`) and for
    /// thin paint (`broad`).
    pub body_medium: f32,
    pub thin_medium: f32,
    /// How unevenly each pile is mixed (relative sd of proportions).
    pub mix_jitter: f32,
    /// Surface relief and gloss for the final lighting.
    pub relief: (f32, f32),
}

impl Style {
    /// A profile built from notes/research/friedrich_materials.md.
    ///
    /// - Plain linen, 15 × 13 threads/cm (10–16 threads/cm proxy range, §1),
    ///   440 mm wide.
    /// - Ground (§2): two knifed layers (110 µm and 70 µm) that level the
    ///   weave, then a brushed top layer (60 µm) whose striations stay;
    ///   total 240 µm (proxy range ~150–300 µm).
    /// - `Palette::friedrich_1820` (§4).
    pub fn friedrich() -> Self {
        Style {
            name: "Caspar David Friedrich",
            width_mm: 440.0,
            linen: Linen { warp_per_cm: 15.0, weft_per_cm: 13.0, ..Linen::fine(1) },
            raw: hex("#a8966f"),
            ground: vec![
                Ground { color: hex("#9a5a36"), hiding: 0.8, um: 110.0, stiff: 0.25, apply: Apply::Knife { texture: 0.35 } },
                Ground { color: hex("#b08457"), hiding: 0.8, um: 70.0, stiff: 0.3, apply: Apply::Knife { texture: 0.3 } },
                Ground { color: hex("#a9785a"), hiding: 0.8, um: 60.0, stiff: 0.35, apply: Apply::Brush },
            ],
            broad: Tool { lay: 0.55, push: 0.03, ragged: 0.4, ..Tool::filbert(22.0) },
            body: Tool { lay: 0.7, push: 0.06, ..Tool::filbert(9.0) },
            detail: Tool::round_sable(2.2),
            line: Tool::rigger(0.6),
            blender: Some(Tool { pickup: 0.15, run: 45.0, ..Tool::badger(40.0) }),
2025-vibecoding-starter-kit
AAAAAAAAA
activity-bot
aip
aiproto
alice.institute
allthethingsivedone.com
anime-sedai
antiantibot.tar.gz
aoc

            blender: Some(Tool { pickup: 0.15, run: 45.0, ..Tool::badger(40.0) }),
            blend_passes: 3,
            blend_pressure: 0.5,
            palette: Palette::friedrich_1820(),
            body_medium: 0.2,
            thin_medium: 0.45,
            mix_jitter: 0.06,
            relief: (0.06, 0.006),
        }
    }

    /// `friedrich` on a 1714 mm canvas of 12 × 11 threads/cm linen, with
    /// `Palette::friedrich_early` and the three-layer ground of
    /// notes/research/friedrich_materials.md §2: bright red, then two light
    /// brown layers, the first two knifed, the third rolled on (a fine
    /// texture) [CATS p.127].
    pub fn friedrich_early() -> Self {
        Style {
            width_mm: 1714.0,
            linen: Linen { warp_per_cm: 12.0, weft_per_cm: 11.0, ..Linen::fine(1) },
            ground: vec![
                Ground { color: hex("#b0583a"), hiding: 0.85, um: 110.0, stiff: 0.25, apply: Apply::Knife { texture: 0.35 } },
                Ground { color: hex("#c9ad8a"), hiding: 0.8, um: 70.0, stiff: 0.3, apply: Apply::Knife { texture: 0.3 } },
                Ground { color: hex("#d8c7ab"), hiding: 0.8, um: 30.0, stiff: 0.5, apply: Apply::Roller },
            ],
            palette: Palette::friedrich_early(),
            ..Self::friedrich()
        }
    }

    /// A primed canvas: this style's linen and physical width (`width_mm`),
    /// with the ground layers applied bottom first.
    pub fn prepare(&self, width_px: usize, aspect: f32, seed: u64) -> Canvas {
        self.prepare_on(Canvas::new(width_px, aspect, self.raw), seed)
    }

    /// `prepare`, holding only the window `crop` (a crop render), whatever
    /// `set_crop` says.
    pub fn prepare_window(&self, width_px: usize, aspect: f32, seed: u64, crop: Option<crate::canvas::Crop>) -> Canvas {
        self.prepare_on(Canvas::new_window(width_px, aspect, self.raw, crop), seed)
    }

    fn prepare_on(&self, c: Canvas, seed: u64) -> Canvas {
        let mut c = c
            .with_size_mm(self.width_mm)
            .with_linen(Linen { seed, ..self.linen });
        for (k, g) in self.ground.iter().enumerate() {
            if g.um <= 0.0 {
                continue;
            }
            let s = seed * 31 + k as u64;
            match g.apply {
                Apply::Knife { texture } => c.prime(g.color, g.hiding, g.um, g.stiff, texture, s),
                Apply::Roller => c.prime(g.color, g.hiding, g.um, g.stiff, 0.8, s),
                Apply::Brush => {
                    brush_ground(&mut c, g, s);
                    // (`prime` counts its own layers)
                    c.ground_um += g.um;
                }
            }
        }
        c
    }
}

/// A brushed top ground: the paste is first spread with a broad hog brush
/// in crossing strokes whose direction wanders over the canvas, then laid
/// off while wet with light passes of the unloaded brush held low, which
/// skim rather than plough, level the spreading's stroke edges and leave
/// only fine, broken bristle striations.
fn brush_ground(c: &mut Canvas, g: &Ground, s: u64) {
    let all = Mask::from_fn(c.frame(), |_, _| 1.0);
    let hog = Tool { lay: 1.2, ragged: 0.2, ..Tool::hog_flat(40.0) };
    let col = g.color;
    // the stroke direction drifts over the canvas, patch by patch (~90
    // units = 40 mm; up to ±0.7 rad, horizontal on average)
    let turn = move |x: f32, y: f32| 1.4 * (crate::surface::vnoise(x / 90.0, y / 90.0, s ^ 0x9e37) - 0.5);
    // the paste is pushed a little ahead of the bristles, not ploughed
    // into ridges (with a hog's own push, 0.3, it piles 2x as thick at the
    // stroke edges: tall, sharp crests that thin paint drains off)
    let spread = Handling::new(Tool { push: 0.15, ..hog.clone() })
        .color(move |_, _| col)
        .paint(g.hiding, g.stiff)
        .angle(turn)
        .angle_jitter(0.15)
        .cross(0.5)
        .curve(0.04, 0.3)
        .drift(0.25, 300.0)
        .tail(0.1)
        .broken(0.1)
        .swell(0.12)
        .length(100.0, 250.0)
        .coverage(3.5)
        .pressure(0.8, 0.95)
        .dips(1, (g.um / BRUSHED_UM_AT_FULL).powf(1.0 / BRUSHED_EXP).min(1.0), 0.3)
        .jitter(0.004, 0.002)
        .shake(0.15);
    c.work(&all, &spread, s);
    // laying off: the clean brush drawn lightly through the wet paste, held
    // low so it skims the paste and barely pushes it
    let lay_off = Handling::new(Tool { push: 0.03, ..hog })
        .blender()
        .angle(turn)
        .angle_jitter(0.12)
        .cross(0.15)
        .curve(0.06, 0.4)
        .drift(0.3, 250.0)
        .tail(0.2)
        .broken(0.3)
        .swell(0.25)
        .length(120.0, 380.0)
        .coverage(3.5)
        .pressure(0.35, 0.55)
        .dips(2, 0.0, 0.8)
        .shake(0.3);
    c.work(&all, &lay_off, s + 7);
    c.dry();
}

impl Style {
    /// The broad tool with thin paint (`thin_medium`): strokes 80–220 units
    /// long that bow into long arcs (`curve`) and whose direction wanders
    /// over 350-unit patches (`drift`). Set the direction with `angle`; the
    /// default is horizontal.
    pub fn broad(&self) -> Handling<'_> {
        Handling::new(self.broad.clone())
            .length(80.0, 220.0)
            .coverage(2.5)
            .mixed(&self.palette, self.thin_medium)
            .mix_jitter(self.mix_jitter)
            .pressure(0.55, 0.8)
            .dips(2, 0.4, 0.5)
            .angle_jitter(0.06)
            .curve(0.06, 0.25)
            .drift(0.22, 350.0)
            .tail(0.15)
            .broken(0.08)
            .swell(0.18)
            .ramps(0.12, 0.4)
    }

    /// The body tool with body color (`body_medium`): strokes 20–60 units
    /// long, more bowed and broken than `broad`, the direction wandering
    /// over 150-unit patches. Set the direction with `angle`.
    pub fn body(&self) -> Handling<'_> {
        Handling::new(self.body.clone())
            .length(20.0, 60.0)
            .coverage(2.5)
            .mixed(&self.palette, self.body_medium)
            .mix_jitter(self.mix_jitter * 1.4)
            .pressure(0.6, 0.9)
            .dips(2, 0.56, 0.6)
            .angle_jitter(0.12)
            .curve(0.08, 0.3)
            .drift(0.3, 150.0)
            .tail(0.15)
            .broken(0.1)
            .swell(0.22)
    }

    /// The detail tool with paint thinned by 0.1 medium: strokes 4–14 units
    /// long, clipped to the mask (`clip`).
    pub fn detail(&self) -> Handling<'_> {
        Handling::new(self.detail.clone())
            .length(4.0, 14.0)
            .coverage(3.0)
            .mixed(&self.palette, 0.1)
            .mix_jitter(self.mix_jitter)
            .pressure(0.7, 0.95)
            .dips(3, 0.9 * 0.8, 0.8)
            .clip(true)
            .threshold(0.1)
            .curve(0.04, 0.2)
            .drift(0.1, 60.0)
            .tail(0.1)
            .broken(0.0)
            .swell(0.2)
    }

    /// Short hatched strokes side by side: one family of nearly straight
    /// strokes 5–12 units long, clumped (`clump`), laid area by area. Set
    /// their direction with `angle`, or `cross` them.
    pub fn hatch(&self) -> Handling<'_> {
        Handling::new(Tool { width: self.detail.width * 1.2, ..self.detail.clone() })
            .length(5.0, 12.0)
            .coverage(2.5)
            .mixed(&self.palette, 0.15)
            .mix_jitter(self.mix_jitter)
            .pressure(0.6, 0.9)
            .dips(4, 0.7, 0.7)
            .angle_jitter(0.1)
            .curve(0.03, 0.1)
            .drift(0.15, 40.0)
            .tail(0.08)
            .broken(0.0)
            .swell(0.15)
            .clump(0.5)
            .ramps(0.05, 0.3)
    }

    /// A glaze or thin scumble brushed over dry paint: a soft brush, paint
    /// that is mostly medium (`medium` ≈ 0.85–0.95 for a transparent glaze,
    /// ≈ 0.6 for a veiling scumble), laid thinly in long strokes. Vary the
    /// depth with `load_at`. The color is the glaze paint's masstone (not
    /// aimed); add `.aim(coats)` to aim it at a look instead.
    pub fn glaze(&self, medium: f32) -> Handling<'_> {
        let soft = Tool { stiffness: 0.3, lay: 0.8, pickup: 0.08, ragged: 0.2, ..Tool::filbert(self.broad.width * 1.2) };
        Handling::new(soft)
            .mixed(&self.palette, medium)
            .by_masstone()
            .mix_jitter(self.mix_jitter * 0.5)
            .length(120.0, 300.0)
            .coverage(2.5)
            .pressure(0.5, 0.7)
            .dips(2, 0.35, 0.5)
            .angle_jitter(0.05)
            .curve(0.05, 0.25)
            .drift(0.2, 350.0)
            .tail(0.12)
            .broken(0.06)
            .swell(0.18)
            .ramps(0.2, 0.4)
    }

    /// Clean soft blender passes over a wet passage: light crossing strokes
    /// (± 0.2 rad to `angle`), worked top to bottom so the blender never
    /// drags paint back up a gradient (change with `order`/`sweep`).
    ///
    /// The blender stays inside the region it is given (`clip(true)`, soft
    /// where the mask is soft). An unclipped blender drags wet paint across
    /// the mask's edge, where later passages show it in their gaps. To blend
    /// across an edge, give it a mask that spans the edge, or
    /// `.clip(false)`.
    pub fn blend(&self) -> Option<Handling<'_>> {
        let t = self.blender.clone()?;
        Some(
            Handling::new(t)
                .length(120.0, 300.0)
                .coverage(3.0)
                .pressure(self.blend_pressure * 0.8, self.blend_pressure)
                .dips(3, 0.0, 0.9)
                .blender()
                .angle_jitter(0.05)
                .cross(0.2)
                .curve(0.06, 0.3)
                .drift(0.2, 300.0)
                .broken(0.0)
                .clip(true)
                .sweep(std::f32::consts::FRAC_PI_2),
        )
    }

    /// A brush held for lines.
    pub fn line_tool(&self, width: f32) -> Tool {
        Tool { width, length: width * 5.0, ..self.line.clone() }
    }

    /// Scumbling: the body tool worked back and forth (`scrub(3)`) with
    /// paint thinned by 0.5 medium, strokes 10–20 units long, the brush's
    /// wide axis across its travel (`Orient::Across`).
    pub fn scumble(&self) -> Handling<'_> {
        Handling::new(self.body.clone()).scrub(3).mixed(&self.palette, 0.5).length(10.0, 20.0).orient(Orient::Across)
    }
}

