        veil(&mut c, r4, 10.0, 45.0, 110.0, 1.2, 302);
    }
    if o.stage("third range", &mut c, &mut rng) {
        range(&mut c, &st, r3, 110.0, (0.0, 0.0), hex("#8a889f"), 60.0, 311);
        veil(&mut c, r3, 12.0, 50.0, 110.0, 1.3, 312);
