            // branches, top to bottom: from the trunk out and down, the tips
            // lifting a little
            let n = (span / 2.6) as usize;
            let mut br = paint::Held::new(paint::Tool { point: 0.8, ..paint::Tool::round_sable(2.2) }, fr.seed + 1);
