    // sky from above and behind
    let (rock_m, rock_lit) = {
        let mut form = paint::Form::new(f);
        let gy = |x: f32| fg(x);
        let solids = [
            paint::Sdf::block([708.0, gy(708.0) + 17.0, 0.0], [92.0, 34.0, 60.0], 3.0).turn([708.0, gy(708.0) + 17.0, 0.0], 0.35, 0.15, -0.04).rough(3.0, 14.0, 71, true),
            paint::Sdf::block([752.0, gy(752.0) + 20.0, -6.0], [54.0, 30.0, 44.0], 3.0).turn([752.0, gy(752.0) + 20.0, -6.0], -0.4, 0.2, 0.12).rough(2.6, 12.0, 72, true),
            paint::Sdf::block([672.0, gy(672.0) + 20.0, 6.0], [40.0, 26.0, 36.0], 3.0).turn([672.0, gy(672.0) + 20.0, 6.0], 0.5, 0.2, -0.15).rough(2.4, 12.0, 78, true),
            paint::Sdf::ellipsoid([298.0, gy(298.0) + 9.0, 0.0], [22.0, 13.0, 18.0]).rough(3.0, 11.0, 73, true),
            paint::Sdf::ellipsoid([58.0, gy(58.0) + 10.0, 0.0], [30.0, 14.0, 22.0]).rough(3.5, 13.0, 74, true),
            paint::Sdf::ellipsoid([880.0, 668.0, 20.0], [44.0, 18.0, 26.0]).rough(3.5, 14.0, 76, true),
        ];
        for s in solids.iter() {
            form.add(s, 5.0);
        }
