    let fx = FIGURE_X;
    let fb = fg(FIGURE_X) + 0.5;
    let coat = Mask::from_shape(f, paint::Shape::new().smooth_poly(&[
        (fx - 6.21, fb - 46.57), (fx - 2.88, fb - 48.30), (fx + 2.88, fb - 48.30), (fx + 6.21, fb - 46.57),
        (fx + 7.24, fb - 41.40), (fx + 7.36, fb - 29.90), (fx + 8.51, fb - 18.40), (fx + 1.15, fb - 17.25), (fx - 7.82, fb - 18.40), (fx - 7.13, fb - 29.90), (fx - 7.24, fb - 41.40),
    ]));
    let legs = Mask::from_shape(f, paint::Shape::new()
        .poly(&[(fx - 5.06, fb - 19.55), (fx - 1.15, fb - 19.55), (fx - 1.84, fb - 0.57), (fx - 5.29, fb - 0.23)])
        .add(paint::Shape::new().poly(&[(fx + 1.15, fb - 19.55), (fx + 5.17, fb - 19.55), (fx + 5.52, fb - 0.23), (fx + 2.07, fb - 0.57)])));
    let head = Mask::from_shape(f, paint::Shape::new().ellipse(fx, fb - 51.98, 3.3, 3.9).add(paint::Shape::new().ellipse(fx - 0.23, fb - 55.66, 4.4, 1.5)));
    let figure = coat.clone().union(&legs).union(&head);
